// GENERATED by tools/merge_block.py from the 2 per-section component(s).
// Do not hand-edit; regenerate.
//
// ONE block for the whole page. 2 separate blocks would each cost a `block`
// table and a `_locales` table, doubled for versions — 8 tables that exist
// only because there is more than one of them. Groups are column PREFIXES, so
// folding each section into a group pays that once: 28 tables become 24.
// The 5 array(s) still cost what they cost; nothing else does.
//
// The price is that the running order is FROZEN here. An editor cannot drag a
// section or remove one. That was the explicit trade — this page is a designed
// narrative, not an editorial sequence.
//
// Each section keeps its own `rd-lg rd-lg<name>` root class and its own
// anchorId, so rd-lg.css still reaches it and the page's internal links
// still resolve. It also means the Stage 7 harness can still verify one
// section at a time with --ours "rd-lg<name>".

// A slice of the block's props, as one section sees them.
type Sec<K extends keyof Props> = NonNullable<Props[K]>
const SectionTop: React.FC<Partial<Sec<'top'>>> = ({ anchorId, intro, title }) => {
  return (
    <section style={{
      background: "var(--tint)",
      borderBottom: "1px solid rgba(81, 71, 69, 0.16)"
    }} className="rd-lg rd-lgtop" id={anchorId || undefined}>
      <div style={{
        maxWidth: "1240px",
        margin: "0px auto",
        /* 136px top, where the mockup draws 72.
         *
         * `.rd-header` carries `margin-bottom: -64px` so a TRANSPARENT header
         * can sit over the block beneath it. The legal pages' header is solid
         * and the pull applies anyway, so this section starts 64px higher than
         * its own box claims: the header's bottom edge is at 73 and the h1's
         * top landed at 9 + 72 = 81, eight pixels clear of it instead of the
         * seventy-two the design asks for.
         *
         * 72 + 64 restores exactly that gap. The same compensation is on
         * PgHero (22 -> 86) and the Standards hero (48 -> 112) for the same
         * reason; the real fix is to stop applying the pull when
         * data-over="0", which wants its own pass across every page already
         * nudged.
         *
         * Only the top needs it. rd-lg.css overrides the SIDE padding above
         * 900px and never touches padding-top, so this one value covers every
         * width. */
        padding: "136px 20px 48px"
      }} data-d="pad">
        <h1 style={{
          fontFamily: "var(--nb1-font-primary)",
          fontWeight: "400",
          fontSize: "clamp(38px, 7cqi, 60px)",
          lineHeight: "1.02",
          letterSpacing: "-0.035em",
          maxWidth: "17ch",
          textWrap: "balance",
          margin: "0px"
        }} data-d="bigh">{title}</h1>
        <p style={{
          fontFamily: "var(--nb1-font-secondary)",
          fontSize: "clamp(17px, 2.2cqi, 20px)",
          lineHeight: "1.6",
          color: "rgba(81, 71, 69, 0.86)",
          margin: "20px 0px 0px",
          maxWidth: "58ch",
          textWrap: "pretty"
        }}>{intro}</p>
      </div>
    </section>
  )
}

