// `className="rd-lgblocks"` on a standalone RichText is load-bearing, not
// decoration. A `rich` BINDING stands in for one node — the bound element is the
// block — so the renderer's <p> is a wrapper the mockup does not have. A RichText
// mounted on its own has no such node, and its paragraphs ARE the mockup's. The
// class is how the two call sites are told apart, by rd-lg.css and by the
// harness alike, and the real RichText merges it onto its own wrapper.

// The lettered sub-list inside an item body. Exactly one item across the four
// pages has one — Terms 6.6, whose a) and b) are the two exclusions from the
// right of withdrawal — so every other item renders nothing here.
const RdLgSubRows: React.FC<{ rows?: LgRow[] | null }> = ({ rows }) => (
  <>
    {(rows || []).map((row, i) => (
      <RdLgSubRow key={i} label={row.label} body={row.body} />
    ))}
  </>
)

// What a panel holds after its label/value rows: Cookie §4's paragraph, its
// table, and the paragraphs after it. Privacy §7 leaves all three empty and this
// renders nothing, which is why one panel component serves both pages.
const RdLgPanelTail: React.FC<{
  body?: LgPart['body']
  caption?: LgPart['caption']
  cols?: LgPart['cols']
  tableRows?: LgRow[] | null
  after?: LgPart['after']
}> = ({ body, caption, cols, tableRows, after }) => (
  <>
    {body?.root ? (
      <RichText data={body} className="rd-lgblocks" enableGutter={false} enableProse={false} />
    ) : null}
    {tableRows?.length ? (
      <RdLgTable caption={caption} cols={cols} rows={tableRows} />
    ) : null}
    {after?.root ? (
      <RichText data={after} className="rd-lgblocks" enableGutter={false} enableProse={false} />
    ) : null}
  </>
)

// A panel's label/value rows and its table rows are the SAME stored array. No
// panel on any of the four pages has both — measured — and a second array would
// have cost four tables and pushed the deepest table name past Postgres's
// 63-byte identifier limit, where it collided with its own parent and killed the
// migration. `cols.c1` is the discriminator: a panel that declares a column
// heading is a table.
type LgPanelProps = {
  title?: LgPart['title']
  rows?: LgRow[] | null
  body?: LgPart['body']
  caption?: LgPart['caption']
  cols?: LgPart['cols']
  tableRows?: LgRow[] | null
  after?: LgPart['after']
}

// The dispatcher. `item` is the default rather than a case of its own: a part
// with no kind set is an item, which is what 36 of the 41 clauses are made of
// and what an editor adding a clause will want without choosing anything.
const RdLgPart: React.FC<{ part: LgPart }> = ({ part }) => {
  switch (part?.kind) {
    case 'panel': {
      const isTable = Boolean(part.cols?.c1)
      return (
        <RdLgPanel
          title={part.title}
          rows={isTable ? null : part.rows}
          body={part.body}
          caption={part.caption}
          cols={part.cols}
          tableRows={isTable ? part.rows : null}
          after={part.after}
        />
      )
    }
    case 'grid':
      return <RdLgGrid cards={part.rows} />
    case 'prose':
      // No wrapper element: the mockup's Annex paragraphs are direct children
      // of the clause body's flex column, and a wrapper would collapse the nine
      // of them into one flex item. rd-lg.css gives Payload's own RichText
      // wrapper `display: contents` so it leaves the box tree alone.
      return part.body?.root ? (
        <RichText data={part.body} className="rd-lgblocks" enableGutter={false} enableProse={false} />
      ) : null
    default:
      return <RdLgItem number={part.number} body={part.body} rows={part.rows} />
  }
}

